/* Fonts are bundled locally via @fontsource-variable in src/main.tsx — no remote @import. */

:root {
  /* Light theme — clean warm white */
  --bg: #fafaf8;
  --bg-elevated: #f0efeb;
  --surface: #ffffff;
  --surface-hover: #f7f6f3;
  --card: #ffffff;
  --card-hover: #f7f6f3;

  /* Warm amber accent + teal secondary */
  --accent: #a56a14;
  --accent-dim: #8f5a0f;
  --accent-glow: rgba(196, 127, 30, 0.1);
  --accent-glow-strong: rgba(196, 127, 30, 0.22);
  --teal: #1a9e8f;
  --teal-dim: rgba(26, 158, 143, 0.1);

  /* Status colors */
  --success: #1a9e6e;
  --success-dim: rgba(26, 158, 110, 0.1);
  --error: #dc3545;
  --error-dim: rgba(220, 53, 69, 0.08);
  --info: #3b7dd8;
  --info-dim: rgba(59, 125, 216, 0.1);


